-- 185_replace_decision_99_2023_insurance_ifrs17_egas50_implementation_guide_ocr_corrupted_single_row_with_page_headers_and_back_cover_as_intro_and_5_sections.sql
--
-- إعادة رفع «دليل إجراءات وضوابط تطبيق معيار المحاسبة المصرى رقم (50) الخاص بعقود التأمين» (الهيئة العامة للرقابة المالية، مايو 2023) المسجَّل فى laws تحت القرار رقم (99) لسنة 2023
-- ("بشأن إصدار دليل إجراءات وضوابط تطبيق معيار المحاسبة المصرى رقم 50 (عقود التأمين)"): مقدمة وخمسة أقسام (أولاً إلى خامساً)، بلا مواد مرقّمة ولا فصول (فمفاتيح الصفوف كلها article_suffix_order = 0).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية OCR) =====
-- مخزَّن بالبذور صف واحد (article_no = 1، 14277 حرفاً، hierarchical_location = "النص الكامل (وثيقة غير مقسّمة لمواد قانونية مرقّمة)") ناتج عن OCR للملف كله، وبه:
-- (1) صفحة الغلاف الأمامى مقروءة تلفاً ("الهيئة العامة للرقابة المكالية" و"تطبيق معيار المحاسبة المصرى رقم (0:0)" و"2003" بدل "2023") وصفحة الغلاف الخلفى (مجمع المعرفة والثقافة المالية) نصاً مشوهاً بلا معنى فى آخر الصف؛
-- (2) ترويسات وتذييلات الصفحات داخل المتن ("الدليل الاسترشادى لإجراءات وضوابط تطبيق معيار..." و"الهيئة العامة للرقاية المالية" و"نبنى الجسور لا الحواجز" وأرقام الصفحات المشوهة)، تقطع الجمل بين الصفحات؛
-- (3) كل الدليل فى صف واحد بلا أقسام (أولاً إلى خامساً) فلا يُستشهد بقسم منه ولا يُسترجع جزء منه على حدة؛ ونهايات أسطر CRLF (294 موضعاً)؛
-- (4) تاريخ سريان هو تاريخ تشغيل البذر (2026-10-09) لا تاريخ الدليل.
--
-- ===== المصدر والمنهجية =====
-- PDF الدليل (9 صفحات: غلاف، وسبع صفحات متن، وغلاف خلفى؛ 1.8 ميجابايت) قدّمه صاحب المشروع؛ هو صور ممسوحة بالألوان (200 نقطة للبوصة) مدارة 90 درجة بلا طبقة نص، لا علامة مائية عليها. دُوِّرت الصور واستُخرج النص آلياً بـOCR ثم قُرئ كل مقطع من كل صفحة بصرياً وقوبل به، وصُحّح النص على المقروء: صُحّحت كلمات مثل "ثلاث الأطراف" إلى "ثلاثى الأطراف"، وأُعيدت عناوين الأقسام الفرعية التى أسقطها الـOCR ("1- حقوق والتزامات شركة التأمين (الجهة التى تعهد الخدمة)" وبقيتها).
-- ثم قوبل النص النهائى بمخرجات OCR مستقلة على الصفحات السبع كلمة بكلمة، فلم يبق فرق فى لفظ غير ضجيج التعرف (التشوهات والأرقام الهندية وانقسام كلمة "المعيار").
-- حُذفت صفحتا الغلاف، وترويسة كل صفحة ("الهيئة العامة للرقابة المالية - FINANCIAL REGULATORY AUTHORITY" و"الدليل الاسترشادى لإجراءات وضوابط ...")، وتذييلها ("نبنى الجسور لا الحواجز" / "Building Bridges not Walls" ورقم الصفحة).
-- عنوان الدليل "دليل إجراءات وضوابط تطبيق معيار المحاسبة المصرى رقم (50) الخاص بعقود التأمين" وجهة الإصدار وتاريخ الغلاف ("مايو 2023") فى hierarchical_location للمقدمة (كما هى مطبوعة؛ لا يذكر الدليل رقم القرار ولا تاريخه، فلم يُنسب إليه شىء غير المطبوع).
-- الدليل بلا ديباجة ولا اطلاعات ولا توقيع ولا مواد؛ فالمقدمة (article_no = 0) هى الفقرة التمهيدية المطبوعة أسفل العنوان ("تلتزم شركات التأمين ... الشفافية والإفصاح")، وكل قسم من الأقسام الخمسة المرقّمة بالحروف (أولاً: خطة وآليات تطبيق المعيار؛ ثانياً: التعاقد مع جهات استشارية لتقديم الدعم لتطبيق المعيار؛ ثالثاً: متطلبات تطبيق المعيار؛ رابعاً: أنظمة تكنولوجيا المعلومات؛ خامساً: حقوق والتزامات أطراف التعاقد لتقديم الخدمات التكنولوجية) صف واحد (article_no = 1 إلى 5) عنوانه عنوان القسم كما طُبع، ومتنه بنوده كما طُبعت بلا إسقاط ولا إضافة؛ البنود المرقّمة "N- ..." والفرعية "أ- ..." سطراً لكل بند، وعناوين البنود الفرعية فى القسم خامساً ("1- ..." و"2- ..." و"3- ...") أسطراً قائمة بذاتها.
-- لا تعديل على لفظ المطبوع. أُبقيت كتابته بلا تعديل: "أدني" و"مدي" و"علي" و"أخر" و"تري" بالياء، و"اي" و"او" و"اعمال" و"ابرام" و"اخطار" و"احقية" و"الاحكام" و"الاشراف" و"امن" بلا همزة، و"إلتزاماً" و"الإستعانة" و"إحتساب" و"إتباعها" بالهمزة، و"مسئول" و"مسئولية" بالهمزة على النبرة، و"و/ أو" بمسافة فى البند 3 من القسم أولاً، و"قانونا" بلا تنوين فى اتفاقية التعهيد، و"مقرا" بلا تنوين فى البند 3-أ من القسم ثانياً ("مقراً" بالتنوين فى 3-ت)، والنقطة الملتصقة بآخر الجملة، والنقطتان والشرطة المتجاورتان فى "بعقود التأمين: -على"، والمصطلحات الإنجليزية بين أقواس (Future cash flows وDiscount rates وRisk adjustment وKPIs).
-- كُتب تنوين الفتح على الحرف السابق للألف ("وفقًا" و"داخليًا") بالصيغة المعتمدة فى باقى الهجرات (المطبوع يضعه فوق الألف).
-- الأرقام لاتينية كما طُبعت، وأُسقطت الضمة وغيرها من علامات التشكيل الصغيرة والتطويل، وضُبطت المسافات حول الفاصلة والنقطتين (" ، " و" :"). الشرطة بين العناصر المتعاطفة كُتبت "-" بمسافتين كما فى باقى الهجرات.
--
-- ===== الهيكل =====
-- 6 صفوف، 6 نسخ (version_no = 1): مقدمة الدليل (article_no = 0) ثم الأقسام 1 إلى 5 بلا hierarchical_location إلا للمقدمة. أُبقى مفتاح المادة المخزَّنة (1، 0) فيبقى لها صف (القسم أولاً الآن) فلا تعيد بذور 004/005/006 إدراج الصف القديم (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2023-05-01: تاريخ مؤقت مُعلَن. الدليل لا يذكر تاريخ إصداره ولا نشره ولا العمل به إلا شهر "مايو 2023" على الغلاف، وموعد تقديم خطة العمل للهيئة 30 مايو 2023 (القسم أولاً، البند 1)، فهو صادر قبل ذلك؛ سُجّل أول الشهر المطبوع على الغلاف.
-- ويُراجع المراجع القانونى هذا التاريخ على أصل القرار 99 لسنة 2023 (وهو غير مرفق بالمصدر المقدَّم). كان القديم تاريخ تشغيل البذر لا تاريخ سريان. لا تُعدَّل بيانات laws (التاريخ ورقم القرار والعنوان) فى هذه الهجرة.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (6 صفوف بمقدمة سليمة والقسم 5 موجود)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، أو بقايا تلف،
-- أو محتوى الأقسام، أو إجمالى الطول 12786 حرفاً).
--
-- ملاحظة تشغيلية: الصفوف الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix185$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[185] القرار 99/2023 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 6
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'مقدمة الدليل' AND body LIKE 'تلتزم شركات التأمين العاملة%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[185] القرار 99/2023 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[185] أُزيلت % مادة من القرار 99/2023 (نص مخزَّن صف واحد ملوَّث بأخطاء OCR وبه ترويسات وتذييلات الصفحات وصفحة الغلاف الخلفى)', v_n;
  END IF;
END
$fix185$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$دليل إجراءات وضوابط تطبيق معيار المحاسبة المصري رقم (50) الخاص بعقود التأمين (الهيئة العامة للرقابة المالية - مايو 2023)$h0$, $t0_0$مقدمة الدليل$t0_0$, $b0_0$تلتزم شركات التأمين العاملة بالسوق المصري مراعاة تطبيق الضوابط الواردة بدليل الإجراءات التالي كحد أدني لتطبيق معيار المحاسبة المصري رقم (50) بهدف ضمان التطبيق السليم لمتطلبات المعيار وعرض البيانات المالية التي تعبر عن المركز المالي الحقيقي للشركة وتحقيق أفضل مستويات الشفافية والإفصاح$b0_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$أولًا: خطة وآليات تطبيق المعيار$t1_0$, $b1_0$1- وضع خطة عمل يتم اعتمادها من مجلس إدارة الشركة لتطبيق متطلبات المعيار تتناسب مع طبيعة نشاط الشركة والتوقيتات الزمنية للتطبيق مع موافاة الهيئة بتلك الخطة في موعد أقصاه 30 مايو 2023 وذلك إلتزامًا بالجدول الزمني الوارد بخارطة الطريق الموضوعة لتطبيق المعيار والتي سبق إبلاغ شركات التأمين بها.
2- تشكيل لجنة لتطبيق المعيار يتضمن أعضاؤها كحد أدني (الرئيس التنفيذي للشركة أو من يفوضه - المدير المالي - مسئول المخاطر - مسئول الاكتتاب - مسئول إعادة التأمين - المسئول الإكتواري - مسئول نظم المعلومات - مسئولي الرقابة الداخلية والالتزام بالشركة - أي مسئول أخر تري الشركة ضمه إلى تشكيل اللجنة من أجل تحقيق هدف تطبيق المعيار).
3- تتولي اللجنة دراسة ووضع آليات تطبيق المعيار وتحديد عمًا إذا كانت الشركة لديها من الإمكانيات الفنية والتكنولوجية والبشرية التي تمكنها من التطبيق الكامل للمعيار داخليًا أم سيتم الإستعانة بواحدة أو أكثر من الجهات الاستشارية التي ستقوم بتقديم الدعم الفني المحاسبي و/ أو الإكتواري و/أو التكنولوجي للقيام بأعمال التطبيق مع عدم الإخلال بمسئولية الشركة عن التطبيق الصحيح لمتطلبات المعيار مع عرض ذلك الأمر على مجلس إدارة الشركة.
4- تحدد اللجنة الاحتياجات التدريبية لكافة المستويات الإدارية للشركة (التنفيذية والرقابية) بالشكل الذي يضمن إلمام العاملين بالشركة لمتطلبات تطبيق المعيار.
5- تجتمع اللجنة بشكل دوري لمتابعة أعمال التنفيذ والتدريب وفقا لجدول زمني بخطة العمل الموضوعة ، ويتم عرض نتائج تلك الاجتماعات على لجان الرقابة الداخلية والمخاطر ومجلس إدارة الشركة.$b1_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$ثانيًا: التعاقد مع جهات استشارية لتقديم الدعم لتطبيق المعيار$t2_0$, $b2_0$تقع مسئولية "اختيار واحد أو أكثر من الجهات الاستشارية لتقديم الدعم المحاسبي و/أو الإكتواري و/أو التكنولوجي من أجل التطبيق الأمثل للمعيار" على شركة التأمين وذلك مع الأخذ في الاعتبار ما يلي :
1- قيام شركة التأمين بدراسة كافة العروض المقدمة لديها من قبل الجهات الاستشارية بعناية والتحقق عما إذا كانت تلك الجهات لديها من الخبرات التي يتطلبها تطبيق المعيار من النواحي المحاسبية والاكتوارية والتكنولوجية وكذا وجود الكوادر البشرية بالشكل الذي يمكنها من تقديم الدعم الفني والتقني لتطبيق المعيار بالشكل الأمثل أخذا في الاعتبار عنصري الجودة والتكلفة.
2- تحقق شركة التأمين قبل إبرام التعاقد مع اي جهة استشارية تعمل داخل مصر من الأتي :
أ- الكيان القانوني للجهة الاستشارية أو من يمثلها داخل جمهورية مصر العربية على أن يتم التعامل مع أحد الجهات الاستشارية الخاضعة لرقابة الهيئة والمقيدة كشخصية اعتبارية أو أشخاصها الطبيعيين العاملين بها بأحد السجلات المهنية المرتبطة بتطبيق المعيار مثل (سجل مراقبي الحسابات بالهيئة - سجل الخبراء الإكتواريين بالهيئة - سجل شركات التعهيد المعد وفقًا لمتطلبات قانون تنظيم وتنمية استخدام التكنولوجيا المالية رقم 5 لسنة 2022).
ب- خبرات وسابقة اعمال تلك الجهة الاستشارية سواء داخل أو خارج جمهورية مصر العربية.
ت- تمتع الجهة الاستشارية وأعضائها القائمين على التطبيق بحسن السمعة والكفاءة المهنية في مجالها.
ث- صلاحية وكفاءة النظام التكنولوجي الذي ستقوم الجهة الاستشارية بإعداده لشركة التأمين بغرض تطبيق المعيار والتحقق من مدي تناسبه مع طبيعة نشاط الشركة وتكامله مع نظام المعلومات المستخدم بالشركة وذلك بهدف ضمان التطبيق الأمثل للمعيار.
3- حال رغبة الشركة التعاقد مع إحدى الجهات الاستشارية الأجنبية التي ليس لها كيان قانوني داخل جمهورية مصر العربية ، فإنه يتعين على شركة التأمين قبل إبرام التعاقد التحقق مما يلي :
أ- الكيان القانوني لتلك الجهة الاستشارية بالدولة التي تتخذها مقرا لها وتحديد الجهة الرقابية التي تخضع تلك الجهة الاستشارية وأعضائها لرقابتها مع وجود المستندات الدالة على ذلك.
ب- خبرات وسابقة أعمال تلك الجهة الاستشارية في تقديم الخدمات المحاسبية - الإكتوارية - التكنولوجية وبصفة خاصة سابقة أعمالها وتعاقداتها لتطبيق المعيار الدولي رقم (17) المعادل له معيار المحاسبة المصري رقم (50).
ت- تمتع الجهة الاستشارية بحسن السمعة والكفاءة المهنية في مجالها داخل الدولة التي تتخذها مقرًا لها وخارجها.
ث- صلاحية وكفاءة النظام التكنولوجي الذي ستقوم الجهة الاستشارية بإعداده لشركة التأمين بغرض تطبيق المعيار والتحقق من مدي تناسبه مع طبيعة نشاط الشركة وتكامله مع نظام المعلومات المستخدم بالشركة وذلك بهدف ضمان التطبيق الأمثل للمعيار.
ج- عند إجراء التعاقد مع الجهة الاستشارية الخارجية فإن شركة التأمين يمكنها تضمين طرف ثالث "محاسبي/إكتواري/تكنولوجي له مقر قانوني في مصر ولديه الخبرة المهنية في الأعمال المحاسبية و/أو الإكتوارية و/أو التكنولوجية وأن يكون مقيدًا بسجلات مراقبي الحسابات أو الخبراء الإكتواريين بالهيئة أو سجل شركات التعهيد المعد وفقًا لمتطلبات قانون تنظيم وتنمية استخدام التكنولوجيا المالية رقم 5 لسنة 2022" وذلك بموجب تعاقد قانوني ثلاثي الأطراف مع قيام شركة التأمين بإحاطة الهيئة بذلك العقد.
4- حال رغبة شركة التأمين الحصول علي الدعم المحاسبي و/أو الإكتواري و/أو التكنولوجي من خلال إحدى الجهات الاستشارية التي يقوم أحد مساهميها من شركات التأمين بالأسواق العالمية أو شركة شقيقة لها بالتعاقد معها فإنه يتعين علي الشركة قبل إبرام التعاقد والبدء في التطبيق التحقق من الكيان القانوني لتلك الجهة الاستشارية وخبرات وسابقة اعمالها في تقديم الخدمات المحاسبية - الإكتوارية - التكنولوجية وكذا التحقق من تمتعها بالخبرات المطلوبة وحسن السمعة والكفاءة المهنية لها وصلاحية وكفاءة النظام التكنولوجي الذي سيتم استخدامه لضمان التطبيق الأمثل للمعيار.
5- تلتزم اللجنة المشكلة من قبل الشركة والمسئولة عن تطبيق المعيار المحاسبي رقم (50) بوضع المعايير التي يتم على أساسها المفاضلة بين الجهات الاستشارية التي ستقوم بتقديم المساعدات اللازمة لتطبيق المعيار وإجراء المقارنات بين تلك الجهات على أن يتم اعتماد الجهة الاستشارية التي سيتم اختيارها في ضوء تلك المعايير من قبل مجلس إدارة الشركة.
6- يتعين على الشركة عند إبرام التعاقد مع الجهة الاستشارية التي ستقوم بتقديم المساعدة والدعم اللازم لتطبيق المعيار أن تتضمن بنود التعاقد الشروط الخاصة بسرية البيانات وفقًا للقوانين المنظمة لذلك وكذا الشروط الجزائية التي تتناسب مع طبيعة الخدمات المقدمة وضرورة عدم وجود تعارض في المصالح بين شركة التأمين والجهة الاستشارية أو من يمثلها مع الإفصاح الكامل عن ذلك لمجلس إدارة الشركة.
7- يتعين على الشركة عند التعاقد وضع الشروط الخاصة بآليات تخزين وحفظ وسرية البيانات وحمايتها مع التحقق من أماكن حفظ البيانات وتوفير النسخ الاحتياطية ووضع خطة للكوارث وتوقف العمل.$b2_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$ثالثًا: متطلبات تطبيق المعيار$t3_0$, $b3_0$1- فيما يتعلق بعقود التأمين : -على شركات التأمين الالتزام الكامل بمتطلبات تطبيق المعيار في شأن تحديد العقود التي تقوم بإصدارها ومدي ربحيتها والتي ينطبق عليها تعريف عقد التأمين الوارد ضمن نطاق عقود التأمين الواردة بالمعيار مع تصنيف وتجميع تلك العقود وفقًا لطبيعة مخاطرها ودرجة تشابهها وتقسيمها وفقًا لفترات إصدارها ومدي ربحيتها وكذا تواريخ الاعتراف بها مع الأخذ في الاعتبار المعالجات الخاصة بتعديلات العقود أو إلغائها.
2- فيما يتعلق بالمكونات غير التأمينية بالعقود : -على الشركة وضع آلية لفصل المكونات غير التأمينية عن عقد التأمين وتحديد المعيار الذي سيتم تطبيقه لمعالجة المكونات غير التأمينية.
3- فيما يتعلق بالتدفقات النقدية المستقبلية (Future cash flows) : -يتعين على شركات التأمين تقدير التدفقات النقدية المستقبلية المتوقع تحصيلها والتدفقات النقدية المتوقع دفعها الناتجة عن عقود التأمين متضمنة كافة المصروفات ذات العلاقة عند الاعتراف بالعقود مع الأخذ في الاعتبار تحديد تكاليف الاستحواذ وتحديد مدي ربحية عقود التأمين مع مراعاة كافة الفرضيات التي يتم استخدامها ضمن المعيار والتي تؤثر علي صافي التدفقات النقدية للعقود.
4- فيما يتعلق بمعدلات الخصم (Discount rates) : -تلتزم الشركات بتحديد معدل الخصم الذي سيتم استخدامه شريطة تحديد الآلية المتبعة في احتساب معدل الخصم وفقًا لمتطلبات المعيار مع مراعاة الحيطة والحذر عند احتسابه بالشكل الذي لا يؤثر سلبيًا على المراكز المالية المستقبلية للشركة وأن يتوافق مع العملة التي يتم تسجيل التزامات العقود بها.
5- فيما يتعلق بإحتساب تعديلات الخطر (Risk adjustment) : -تلتزم شركات التأمين بتعريف وتحديد المخاطر غير المالية وفقًا لمتطلبات المعيار مع تحديد الطريقة التي سيتم إتباعها في تحديد القيمة ومستوي الثقة المستخدم للاحتساب.
6- فيما يتعلق بمناهج قياس العقود : تلتزم شركات التأمين بتحديد المنهج الذي سيتم استخدامه لقياس ومعالجة عقود التأمين وعقود إعادة التأمين المحتفظ بها.
7- فيما يتعلق بالإفصاحات : تلتزم شركات التأمين بمتطلبات الإفصاح التي يتطلبها تطبيق المعيار.$b3_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$رابعًا: أنظمة تكنولوجيا المعلومات$t4_0$, $b4_0$1- يتعين على مجلس إدارة شركة التأمين اعتماد نظام تكنولوجيا المعلومات الذي سيتم استخدامه والمعد من قبل الشركة نفسها أو من خلال أي من الجهات الاستشارية التي تقدم الدعم التقني لتطبيق المعيار على أن يتضمن قدرة النظام على ما يلي كحد أدني :
أ- تجميع العقود وفصل مكوناتها (تأمينية-غير تأمينية).
ب- تطبيق كافة متطلبات مناهج القياس المحاسبية المستخدمة والتي تتناسب مع طبيعة نشاط الشركة.
ت- تقدير التدفقات النقدية المستقبلية وأن يشتمل النظام على الفرضيات الإكتوارية الخاصة بتقدير تلك التدفقات.
ث- احتساب القيمة الحالية للتدفقات النقدية المستقبلية باستخدام معدل الخصم الذي سيتم احتسابه واعتماده.
ج- احتساب قيمة تعديلات المخاطر الغير مالية وهامش الخدمة التعاقدية وفقًا للفرضيات الإكتوارية المستخدمة.
ح- إدارة عمليات عقود إعادة التأمين المحتفظ بها بشكل منفصل.
خ- معالجة التغيرات في الفرضيات الإكتوارية المستخدمة.
د- إعداد القيود المحاسبية بشكل تقني وترحيلها إلى حسابات الأستاذ والأستاذ المساعد وإعداد موازين المراجعة.
ذ- تخزين البيانات على مستوي العقد وأرشفتها.
ر- التكامل مع النظام المحاسبي الأساسي المستخدم وإعداد التقارير المالية والافصاحات المطلوبة وفقًا للمعيار.
2- ضرورة تأكد لجان الرقابة الداخلية والمخاطر وكذا مجلس إدارة الشركة من أن المسئول عن عملية مراجعة أنظمة تكنولوجيا المعلومات على دراية كافية بالممارسات الأفضل لعملية المراجعة في ضوء متطلبات تطبيق المعيار.
3- يتم موافاة الهيئة سنويًا بتقرير بعد عرضه على مجلس إدارة الشركة يوضح مدي دقة أنظمة تكنولوجيا المعلومات على أن يتضمن منهجية المراجعة المتبعة من قبل الشركة وملخص النتائج والإجراءات التصحيحية حال وجود مشاكل على النظام.$b4_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$خامسًا: حقوق والتزامات أطراف التعاقد لتقديم الخدمات التكنولوجية$t5_0$, $b5_0$1- حقوق والتزامات شركة التأمين (الجهة التي تعهد الخدمة) :
أ- يحق لشركة التأمين تعهيد أداء الخدمات التكنولوجية المطلوبة لتطبيق معيار المحاسبة المصري رقم (50) لإحدي الجهات (شركة تعهيد) على أن تكون شركة التأمين مسئولة بشكل كامل عن نتائج أعمال جهة التعهيد فنيًا وقانونيًا.
ب- ضرورة أن يتوافر لدي شركة التأمين الكوادر الفنية التي تمكنها من تقييم سلامة وجودة الاعمال التي ينفذها مقدم التعهيد.
ت- على مجلس إدارة شركة التأمين اعتماد خطة تعهيد متكاملة للخدمات المطلوبة ومفصلة تقدم له من اللجنة المشكلة لتطبيق المعيار.
ث- يتعين على شركة التأمين الالتزام عند إبرام اتفاقية لتعهيد الخدمات التكنولوجية بالبنود الواردة على النحو المفصل في البند رقم (3) مع مقدم خدمة التعهيد كحد أدني.
ج- يتعين على شركة التأمين اخطار الهيئة عند ابرام اتفاقية لتعهيد الخدمات التكنولوجية لأحدي الجهات بغرض تطبيق المعيار ، او عند اجراء أي تعديل جوهري لاتفاقية التعهيد القائمة.
ح- يتعين على شركة التأمين إعداد سياسة تعهيد محددة وواضحة تضمن مؤشرات تقييم الأداء (KPIs) لمتابعة أداء مقدمي خدمات التعهيد.
2- حقوق والتزامات مقدم الخدمة (شركة التعهيد) :
أ- يجب أن يلتزم مقدم خدمة التعهيد بمساعدة شركة التأمين (الجهة العاهدة) في الامتثال بالضوابط الصادرة من الهيئة والمنظمة للعمليات والمهام والأعمال موضوع التعهيد ، والمتضمنة على سبيل المثال "ضوابط التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين والوظائف التكنولوجية الرئيسية".
ب- ضمان أمن بيانات عملاء شركة التأمين وكذلك عدم جواز احتفاظ مقدم التعهيد ببيانات عملاء الشركة والخدمة التي تنفذها وكذلك استخدام الوسائل المناسبة لحماية خصوصية وسرية تلك البيانات والعمل على ضمان عدم الوصول غير المسموح به لتلك البيانات.
ت- وضع إجراءات احترازية بشأن أمن البيانات وخطة استمرارية العمل.
ث- القيام بالإجراءات التصحيحية اللازمة عند ظهور أي خلل في مستوى أداء الخدمات التي تم تعهيدها إليهم وتسجيل كافة الأحداث المرتبطة ، وتمكين شركة التأمين والهيئة من مراجعة تلك الأحداث.
ج- إخطار شركة التأمين والهيئة في حال ما إذا طلبت أي جهة رقابية تخضع لها شركة التعهيد إعمال شئونها الرقابية بالمراجعة والتفتيش ، وبنتائج هذه الأعمال.
3- اتفاقية التعهيد :
تكون اتفاقية التعهيد اتفاقية ملزمة قانونا بين شركة التأمين (الجهة العاهدة) ومقدم خدمة التعهيد (شركة التعهيد) وتتضمن كحد أدني ما يلي :
أ- المدة الزمنية للاتفاقية مثبت بها كل من تاريخ البدء ، وتاريخ الانتهاء ، وتاريخ التجديد.
ب- تحديد نطاق أعمال مقدم الخدمة ومعاير قياس الأداء ، والمخاطر التي يمكن قياسها بشكل واضح ومحدد.
ت- تحديد مؤشرات أداء واضحة للتقييم المستمر لمستوى جودة الخدمة.
ث- الضوابط والإجراءات المتبعة والخاصة بأمن البيانات ومسئولية مقدم الخدمة تجاه تلك البيانات.
ج- نطاق البيانات الواجب حمايتها ، واقتصار تبادل البيانات والمعلومات على ما يكون لازمًا لتنفيذ نطاق الأعمال المحدد.
ح- إدراج بند بشأن سرية البيانات وكذا توقيع اتفاقية عدم إفصاح لضمان امن البيانات وتحديد مدى المسئولية في حالة الخرق الأمني وتسريب المعلومات السرية.
خ- الاحكام الملزمة لتعويض متلقي الخدمة (شركة التأمين) عن أي خسائر او التزامات قد تنشأ نتيجة خرق أمني منسوب إلى مقدم الخدمة.
د- أساليب اخطار مقدم الخدمة لمتلقي الخدمة (شركة التأمين) في حال حدوث الخرق الأمني وتسريب المعلومات السرية.
ذ- تضمين ما يضمن قيام متلقي الخدمة بدوره في الاشراف والرقابة على الأنشطة بشكل فعال ، وحقه بشكل كامل ومستمر في الوصول إلى جميع البيانات والمعلومات المتبادلة لدى مقدم الخدمة.
ر- ضمان احقية متلقي الخدمة في التمكن الكامل من بيانات عملائه في حال فسخ التعاقد او في حالة النزاع ما بين الطرفين.
ز- التزام الموظفين المكلفين من قبل مقدم الخدمة والذين يشاركون في تقديم خدمة تطبيق المعيار ، بالامتثال لمعايير سرية البيانات.
س- حق الهيئة بالحصول مباشرة وفورًا ودون أي شروط على أي معلومات أو مستندات متعلقة بالخدمة المقدمة أو الوصول للنظام المستخدم وكذا التفتيش على أعمال مقدم الخدمة فيما يتعلق بموضوع الخدمة المقدمة.
ش- تضمين الاتفاق إجراءات فض المنازعات بين شركة التأمين وجهة التعهيد (مقدم الخدمة).$b5_0$
  FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-05-01', 'active' FROM ins5_0;

DO $verify185$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 99 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[185] القرار 99/2023 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 6 THEN RAISE EXCEPTION '[185] عدد المواد % بدل 6', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2023-05-01';
  IF v_v <> 6 THEN RAISE EXCEPTION '[185] عدد النسخ % بدل 6', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%المكالية%' OR body LIKE '%مجمعلمعرفة%' OR body LIKE '%نصنعلمعرفة%' OR body LIKE '%اللعيار%' OR body LIKE '%اللالية%' OR body LIKE '%ا معيار%' OR body LIKE '%ثلاث الأطراف%' OR body LIKE '%نبنى الجسور%' OR body LIKE '%نبني الجسور%' OR body LIKE '%Building Bridges%' OR body LIKE '%www.fra%' OR body LIKE '%الاسترشادى%' OR body LIKE '%الهيئة العامة للرقابة المالية%' OR body LIKE '%الرقاية%' OR body LIKE '%(0:0)%' OR body LIKE '%2003%' OR body LIKE '%٪%' OR body LIKE '%���%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%ال يقل%' OR body LIKE '%�%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[185] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'تلتزم شركات التأمين العاملة بالسوق المصري مرا%' AND body LIKE '%أفضل مستويات الشفافية والإفصاح' AND body LIKE '%رقم (50) بهدف ضمان التطبيق السليم لمتطلبات المعيار%' AND body LIKE '%وتحقيق أفضل مستويات الشفافية والإفصاح') THEN RAISE EXCEPTION '[185] مقدمة الدليل غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE '1- وضع خطة عمل يتم اعتمادها من مجلس إدارة الش%' AND body LIKE '%ة والمخاطر ومجلس إدارة الشركة.' AND body LIKE '%في موعد أقصاه 30 مايو 2023%' AND body LIKE '%إلتزامًا بالجدول الزمني الوارد بخارطة الطريق%' AND body LIKE '%5- تجتمع اللجنة بشكل دوري%') THEN RAISE EXCEPTION '[185] القسم 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'تقع مسئولية "اختيار واحد أو أكثر من الجهات ال%' AND body LIKE '%ووضع خطة للكوارث وتوقف العمل.' AND body LIKE '%رقم 5 لسنة 2022).%' AND body LIKE '%المعادل له معيار المحاسبة المصري رقم (50).%' AND body LIKE '%بموجب تعاقد قانوني ثلاثي الأطراف%' AND body LIKE '%7- يتعين على الشركة عند التعاقد%') THEN RAISE EXCEPTION '[185] القسم 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE '1- فيما يتعلق بعقود التأمين : -على شركات التأ%' AND body LIKE '%اح التي يتطلبها تطبيق المعيار.' AND body LIKE '%(Future cash flows) : -يتعين%' AND body LIKE '%(Discount rates) : -تلتزم%' AND body LIKE '%(Risk adjustment) : -تلتزم%') THEN RAISE EXCEPTION '[185] القسم 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE '1- يتعين على مجلس إدارة شركة التأمين اعتماد ن%' AND body LIKE '%حية حال وجود مشاكل على النظام.' AND body LIKE '%(تأمينية-غير تأمينية).%' AND body LIKE '%ر- التكامل مع النظام المحاسبي الأساسي%' AND body LIKE '%3- يتم موافاة الهيئة سنويًا بتقرير%') THEN RAISE EXCEPTION '[185] القسم 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE '1- حقوق والتزامات شركة التأمين (الجهة التي تع%' AND body LIKE '%ين وجهة التعهيد (مقدم الخدمة).' AND body LIKE '%(KPIs) لمتابعة أداء%' AND body LIKE '%3- اتفاقية التعهيد :%' AND body LIKE '%ش- تضمين الاتفاق إجراءات فض المنازعات%' AND body LIKE '%ز- التزام الموظفين المكلفين%') THEN RAISE EXCEPTION '[185] القسم 5 غير سليم'; END IF;
  IF v_len <> 12786 THEN RAISE EXCEPTION '[185] إجمالى طول المواد % بدل 12786', v_len; END IF;
  RAISE NOTICE '[185] القرار 99/2023: 6 مواد و6 نسخ، إجمالى % حرف', v_len;
END
$verify185$;

COMMIT;
